create table if not exists habitflow.users(id uuid primary key,name varchar(150),email varchar(200) unique not null,password_hash text,photo_url text,role varchar(50) not null default 'User',account_status varchar(50) not null default 'Active',plan varchar(50) not null default 'Free',plan_status varchar(50) not null default 'Active',wants_premium_notice boolean default false,onboarding_completed boolean default false,accepted_terms_at timestamp null,accepted_privacy_at timestamp null,last_login_at timestamp null,created_at timestamp not null,updated_at timestamp not null);
create table if not exists habitflow.login_attempts(id uuid primary key,email varchar(200),success boolean,ip_address varchar(100),user_agent text,created_at timestamp not null);
